export const HUD_CSS = '\n.hud{display:flex;flex-wrap:wrap;align-items:center;gap:8px}\n.hud[data-slot=top]{flex-wrap:nowrap}\n.hud[data-slot=menu]{justify-content:center}\n/* The shell host is transparent to pointer events; opt the column back in inside its shadow root\n so both tiles and the gaps between them accept scrolling above the bottom menu. */\n.hud[data-slot=left],.hud[data-slot=right]{flex-direction:column;gap:16px;pointer-events:auto}\n.hud .hud-item{position:relative;display:inline-flex;flex-direction:column;align-items:center;justify-content:center;\n gap:4px;width:40px;height:40px;min-height:40px;padding:0;border:1px solid\n   var(--mp-line);border-radius:12px;\n background:var(--mp-night);color:var(--mp-text)}\n.hud-item[data-capsule]{flex-direction:row;width:auto;padding:0 8px;gap:8px;max-width:100%;white-space:nowrap;font-weight:700}\n.hud-capsule{display:flex;align-items:center;gap:0;padding-right:0;height:40px;\n border:1px solid var(--mp-line);border-radius:12px;background:var(--mp-night)}\n.hud-capsule .hud-item{border:0;background:transparent;padding-right:0;height:38px;min-height:38px}\n.hud .hud-add{box-sizing:border-box;flex:none;display:grid;place-items:center;width:44px;height:44px;min-height:44px;\n padding:0;border:10px solid transparent;border-radius:18px;\n background:var(--mp-violet);background-clip:padding-box;color:var(--mp-on-accent);font-size:18px}\n.hud[data-slot=left] .hud-item,.hud[data-slot=right]\n  .hud-item{width:64px;height:80px;padding:8px 0 6px;\n justify-content:space-between}\n/* Landscape (MPS_L_Lobby: side tiles from the top of the band, 12 px apart): always ONE column\n a side, at the very edge of its side. When the band is lower than the tiles, they shrink (down to\n 56 px) and then the column scrolls; never a second column. Portrait keeps the same column. */\n@media (orientation:landscape) and (min-width:641px){\n/* Content height, capped at the band (+16 px of the -8 px margins): a tall band keeps 80 px tiles and no\n pointer-catching column below them; a short band shrinks the tiles, then scrolls (#884, #607). */\n .hud[data-slot=left],.hud[data-slot=right]{display:flex;flex-direction:column;flex-wrap:nowrap;gap:12px;\n  justify-content:flex-start;height:auto;max-height:calc(100% + 16px);min-height:0;box-sizing:border-box;\n  margin:-8px;padding:8px;overflow-x:hidden;overflow-y:auto;scrollbar-width:none}\n .hud[data-slot=left] .hud-item,.hud[data-slot=right] .hud-item{flex:0 1 80px;height:auto;min-height:56px;\n  padding:6px 0;gap:2px}\n .hud[data-slot=left] .hud-glyph,.hud[data-slot=right] .hud-glyph{display:flex;flex:1 1 auto;min-height:0;align-items:center;justify-content:center}\n .hud[data-slot=left] .hud-glyph>*,.hud[data-slot=right] .hud-glyph>*{height:100%;max-height:40px;width:auto;aspect-ratio:1}\n}\n.hud .hud-item:not(:disabled):hover{background:var(--mp-raised)}\n.hud-item[data-state=locked]{opacity:.5}\n.hud-progress{position:absolute;left:6px;right:6px;bottom:3px;height:3px;border-radius:2px;\n background:var(--mp-line);overflow:hidden;pointer-events:none}\n.hud-progress>span{display:block;height:100%;width:0;background:var(--mp-violet)}\n.hud-progress>span[data-step="1"]{width:10%}\n.hud-progress>span[data-step="2"]{width:20%}\n.hud-progress>span[data-step="3"]{width:30%}\n.hud-progress>span[data-step="4"]{width:40%}\n.hud-progress>span[data-step="5"]{width:50%}\n.hud-progress>span[data-step="6"]{width:60%}\n.hud-progress>span[data-step="7"]{width:70%}\n.hud-progress>span[data-step="8"]{width:80%}\n.hud-progress>span[data-step="9"]{width:90%}\n.hud-progress>span[data-step="10"]{width:100%}\n.hud-value{display:inline-block;font-variant-numeric:tabular-nums}\n.hud-value[data-change=up][data-phase="0"]{animation:hud-up-0 .45s ease-out}\n.hud-value[data-change=up][data-phase="1"]{animation:hud-up-1 .45s ease-out}\n.hud-value[data-change=down][data-phase="0"]{animation:hud-down-0 .45s ease-out}\n.hud-value[data-change=down][data-phase="1"]{animation:hud-down-1 .45s ease-out}\n@keyframes hud-up-0{40%{transform:scale(1.18);color:var(--mp-mint,var(--mp-text))}}\n@keyframes hud-up-1{40%{transform:scale(1.18);color:var(--mp-mint,var(--mp-text))}}\n@keyframes hud-down-0{40%{transform:scale(.9);color:var(--mp-coral)}}\n@keyframes hud-down-1{40%{transform:scale(.9);color:var(--mp-coral)}}\n@media(prefers-reduced-motion:reduce){.hud-value[data-change]{animation:none}}\n.hud-glyph{flex:none;display:grid;place-items:center;font-size:24px;line-height:1}\n.hud-glyph img{object-fit:contain;max-width:100%}\n.hud-label{font-size:12px;font-weight:600;line-height:16px;color:var(--mp-text-2)}\n/* Side tiles are 64 px (D_Lobby): the label is one line that fits the tile, «Достижения» and\n «Инвентарь» whole at 360–390 px, never cut by the tile edge. */\n.hud[data-slot=left] .hud-label,.hud[data-slot=right] .hud-label{max-width:100%;white-space:nowrap;\n font-size:10px;letter-spacing:-.02em;text-align:center}\n@media(max-width:480px){.hud[data-slot=left] .hud-label,.hud[data-slot=right] .hud-label{font-size:9px;letter-spacing:-.05em;overflow:hidden;text-overflow:clip}}\n.hud-badge{position:absolute;top:-6px;right:-6px;min-width:20px;height:20px;padding:0 6px;\n border-radius:99px;background:var(--mp-coral);color:var(--mp-on-accent);\n font:700 12px/20px var(--mp-font-ui);text-align:center;pointer-events:none;box-shadow:0 0 0 2px var(--mp-window-background)}\n.hud-badge[data-kind=dot]{top:1px;right:1px;min-width:12px;width:12px;height:12px;padding:0}\n.hud-badge[data-kind=timer]{top:auto;right:50%;bottom:-8px;transform:translateX(50%);white-space:nowrap}\n/* Side tiles (D_Lobby «Акции»): a coral chip with a clock over the top right corner, the label stays. */\n.hud[data-slot=left] .hud-badge[data-kind=timer],.hud[data-slot=right] .hud-badge[data-kind=timer]{\n top:-8px;right:-6px;bottom:auto;transform:none;display:flex;align-items:center;gap:3px;min-width:0;\n padding:0 6px;font-size:11px;line-height:20px}\n';
